// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
bool judge(vector<int> num, int k, int count) {
    int res = 0;
    for (int i = 0; i < num.size(); i++) {
        res = res + num[i] / k;
        if (num[i] % k){
            res++;
        }
        if (res > count) {
            return false;
        }
    }
    return true;
}
​
int main() {
    string s;
    getline(cin, s);
    vector<string> ans = split(s, " ");
    int h;
    cin >> h;
    int n = ans.size();
    // 每个小时智能吃一颗树上的桃子
    if (n > h) {
        cout << 0;
        return 0;
    }
    vector<int> num(n);
    int maxValue = 0;
    for (int i = 0; i < n; i++) {
        num[i] = stoi(ans[i]);
        maxValue = max(maxValue, num[i]);
    }

    // H等于桃树数量，决定每小时要吃掉一棵树上的桃子
    if (h == n) {
        cout << maxValue;
        return 0;
    }

    int left  = 0, right  = maxValue;
    while (left < right) {
        int mid = (left + right) >> 1;
        if (judge(num, mid, h)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
​
    cout << left;
​
}

