public class Main {
    // 通用 split 函数
    public static List<Integer> split(String str, String delimiter) {
        List<Integer> result = new ArrayList<>();
        String[] parts = str.split(delimiter);
        for (String part : parts) {
            result.add(Integer.parseInt(part));
        }
        return result;
    }
​
    // 判断是否可以用当前 k 在 h 小时内吃完桃子
    public static boolean judge(List<Integer> num, int k, int count) {
        int res = 0;
        for (int n : num) {
            res += n / k;
            if (n % k != 0) {
                res++;
            }
            if (res > count) {
                return false;
            }
        }
        return true;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        List<Integer> num = split(s, " ");
        int h = scanner.nextInt();
        scanner.close();

        int n = num.size();
        // 每个小时智能吃一颗树上的桃子
        if (n > h) {
            System.out.println(0);
            return;
        }
​
        int maxValue = Collections.max(num);
​
        // H等于桃树数量，决定每小时要吃掉一棵树上的桃子
        if (h == n) {
            System.out.println(maxValue);
            return;
        }
​
        int left = 1, right = maxValue;
        while (left < right) {
            int mid = (left + right) / 2;
            if (judge(num, mid, h)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
​
        System.out.println(left);
    }
}
