package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 通用 split 函数
func split(s string, delimiter string) []int {
    parts := strings.Split(s, delimiter)
    result := make([]int, len(parts))
    for i, part := range parts {
        result[i], _ = strconv.Atoi(part)
    }
    return result
}
​
// 判断是否可以用当前 k 在 h 小时内吃完桃子
func judge(num []int, k int, count int) bool {
    res := 0
    for _, n := range num {
        res += n / k
        if n%k != 0 {
            res++
        }
        if res > count {
            return false
        }
    }
    return true
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    s, _ := reader.ReadString('\n')
    s = strings.TrimSpace(s)
    num := split(s, " ")
​
    hStr, _ := reader.ReadString('\n')
    hStr = strings.TrimSpace(hStr)
    h, _ := strconv.Atoi(hStr)
​
    n := len(num)
    if n > h {
        fmt.Println(0)
        return
    }
​
    maxValue := 0
    for _, v := range num {
        if v > maxValue {
            maxValue = v
        }
    }
​
    if h == n {
        fmt.Println(maxValue)
        return
    }
​
    left, right := 1, maxValue
    for left < right {
        mid := (left + right) / 2
        if judge(num, mid, h) {
            right = mid
        } else {
            left = mid + 1
        }
    }
​
    fmt.Println(left)
}
